const PDL_SUPPORT_LIBRARY = [{"id":"pdl-help-01","title":"Create your company account","type":"article","audience":"all","category":"Getting started","summary":"Start a 14-day trial without a credit card.","content":"1) Open the sign-up page.\n2) Enter your company and contact details.\n3) Choose the plan that fits your team.\n4) Accept the Terms and Privacy Policy.\n5) Select [CONFIRM BUTTON NAME] to create the workspace.","url":"","status":"Published","order":100},{"id":"pdl-help-02","title":"Add your first customer and project","type":"article","audience":"office","category":"Getting started","summary":"Create a customer first, then add the project your crew will work on.","content":"1) Open Customers.\n2) Select Add customer.\n3) Save the customer details.\n4) Open Projects.\n5) Select Add project and choose that customer.\n6) Add project details and save.","url":"","status":"Published","order":101},{"id":"pdl-help-03","title":"Invite office users","type":"article","audience":"office","category":"Team","summary":"Give trusted office staff their own secure sign-in.","content":"1) Open Team.\n2) Open User accounts.\n3) Select Add user account.\n4) Choose the office role.\n5) Enter the person’s email.\n6) Share the temporary-password instructions securely.","url":"","status":"Published","order":102},{"id":"pdl-help-04","title":"Add crew members and crews","type":"article","audience":"office","category":"Team","summary":"Keep people and crew assignments organized for reports and scheduling.","content":"1) Open Team.\n2) Select Add team member.\n3) Choose the member’s role.\n4) Select an existing crew or create one.\n5) Add contact information.\n6) Save the team member.","url":"","status":"Published","order":103},{"id":"pdl-help-05","title":"Schedule crews","type":"article","audience":"office","category":"Scheduling","summary":"Put the right crew on the right project and keep the field informed.","content":"1) Open Schedule.\n2) Select the project and date.\n3) Choose a crew or team members.\n4) Set planned hours and activity.\n5) Add additional days if needed.\n6) Send the assignment.","url":"","status":"Published","order":104},{"id":"pdl-help-06","title":"What crew members see on My Day","type":"article","audience":"field","category":"Field work","summary":"My Day shows field users their own assignments and daily work tools.","content":"1) Sign in with your crew account.\n2) Open My Day.\n3) Review today’s assignment.\n4) Acknowledge the assignment.\n5) Start the workday when work begins.\n6) File a daily report when finished.","url":"","status":"Published","order":105},{"id":"pdl-help-07","title":"File a daily report on a phone","type":"article","audience":"field","category":"Field work","summary":"Capture notes, labor, photos, and installed work before leaving the job.","content":"1) Open My Day and choose New daily report.\n2) Confirm the project, date, and crew.\n3) Describe what happened today.\n4) Add photos or voice notes if helpful.\n5) Enter labor and production in Step 2.\n6) Submit to office.","url":"","status":"Published","order":106},{"id":"pdl-help-08","title":"Add photos and voice notes","type":"article","audience":"field","category":"Field work","summary":"Attach clear jobsite evidence to a daily report.","content":"1) Open a new or draft daily report.\n2) Use the photo area to add images.\n3) Add a short caption or tag when prompted.\n4) Select Speak notes to dictate an update.\n5) Review the transcribed note.\n6) Continue to submit the daily.","url":"","status":"Published","order":107},{"id":"pdl-help-09","title":"Add unplanned work","type":"article","audience":"field","category":"Field work","summary":"Record work that was not part of the estimate so the office can review it.","content":"1) Open Step 2 of the daily report.\n2) Select Custom work.\n3) Describe the work completed.\n4) Add labor hours and quantity when known.\n5) Submit the daily.\n6) The office will see the item flagged for review.","url":"","status":"Published","order":108},{"id":"pdl-help-10","title":"Approve daily reports","type":"article","audience":"office","category":"Daily reports","summary":"Only approved dailies count toward project production.","content":"1) Open Action center.\n2) Select a daily that needs review.\n3) Check notes, photos, hours, and quantities.\n4) Correct details if needed.\n5) Select Approve.\n6) Review the updated project actuals.","url":"","status":"Published","order":109},{"id":"pdl-help-11","title":"Set up estimate items","type":"article","audience":"office","category":"Projects","summary":"Use estimate items to compare planned work with approved production.","content":"1) Open the project.\n2) Open Estimate & actual.\n3) Select Add estimate item.\n4) Enter the scope, planned quantity, unit, and budgeted labor hours.\n5) Add estimated cost if your office uses it.\n6) Save the item.","url":"","status":"Published","order":110},{"id":"pdl-help-12","title":"Read Estimate & actual","type":"article","audience":"office","category":"Projects","summary":"See completed quantity, remaining quantity, and labor used for each scope item.","content":"1) Open the project.\n2) Open Estimate & actual.\n3) Find the scope item.\n4) Review completed and remaining quantity.\n5) Review labor used against budget.\n6) Open the item to edit planned values if authorized.","url":"","status":"Published","order":111},{"id":"pdl-help-13","title":"Understand efficiency percentage","type":"article","audience":"office","category":"Insights","summary":"Efficiency compares earned labor from completed work with actual approved labor.","content":"1) Open Production insights.\n2) Choose a date range.\n3) Filter by project, crew, or scope.\n4) Review the efficiency percentage.\n5) Compare results with completed quantity and labor hours.\n6) Use the trend as a conversation starter, not payroll data.","url":"","status":"Published","order":112},{"id":"pdl-help-14","title":"Export CSV reports","type":"article","audience":"office","category":"Insights","summary":"Download report data for a spreadsheet or project meeting.","content":"1) Open Production insights.\n2) Set the date range and filters.\n3) Review the results.\n4) Select Export CSV.\n5) Open the downloaded file in your spreadsheet program.","url":"","status":"Published","order":113},{"id":"pdl-help-15","title":"Who can see pricing","type":"article","audience":"office","category":"Access and permissions","summary":"Company owners control who in the office can view contract values, estimated costs, and pricing.","content":"1) Open Company settings.\n2) Open pricing visibility.\n3) Turn pricing access on or off for office roles.\n4) Select individual office team members if needed.\n5) Save the settings.\n6) Field and crew users do not see pricing.","url":"","status":"Published","order":114},{"id":"pdl-help-16","title":"Use subcontractor guest links","type":"article","audience":"office","category":"Access and permissions","summary":"Share limited project access without giving a subcontractor full company access.","content":"1) Open the project or subcontractor area.\n2) Select Create guest link.\n3) Choose the allowed project access.\n4) Copy the link.\n5) Share it only with the intended subcontractor.\n6) Revoke it when access is no longer needed.","url":"","status":"Published","order":115},{"id":"pdl-help-17","title":"Trial and plans","type":"article","audience":"all","category":"Billing","summary":"Every new company starts with a 14-day trial and no credit card.","content":"1) Start your free trial.\n2) Use the trial to create customers, projects, teams, and reports.\n3) Check days remaining in your workspace.\n4) Choose Starter, Growth, or Pro before the trial ends.\n5) Select Manage plan to continue.","url":"","status":"Published","order":116},{"id":"pdl-help-18","title":"Billing and cancelling","type":"article","audience":"office","category":"Billing","summary":"Plan and billing actions are handled by the company owner or authorized office staff.","content":"1) Open Manage plan.\n2) Review your plan and billing details.\n3) Choose the plan action you need.\n4) For a billing dispute, refund, or cancellation request, contact support with your company name and email.","url":"","status":"Published","order":117}];
const TIME_CARD_HELP = {id:'pdl-help-19',title:'Create, correct, submit, and approve time cards',type:'article',audience:'all',category:'Time cards',summary:'Use a clear Draft → Submitted → Approved workflow while preserving correction history.',content:'1) Field users end their workday or company-time clock to close the card.\n2) Office users can select Add time card to enter a missed card manually.\n3) Correct times while the card is in Draft; overlapping hours are blocked.\n4) Select Submit when the card is ready for office review.\n5) Office users review Submitted cards, then select Approve.\n6) Select Unapprove to return a card to Draft before correcting it.\n7) Deleting a Draft or Submitted card removes it from the list but retains its audit record.\n8) Corrections to a linked time card update that daily report’s labor hours.',url:'',status:'Published',order:118};
const originalReadPlatformForSupport = readPlatform;
readPlatform = function(){
  const platform = originalReadPlatformForSupport();
  const existing = new Set((platform.helpItems || []).map(item => item.id));
  const missing = [...PDL_SUPPORT_LIBRARY,TIME_CARD_HELP].filter(item => !existing.has(item.id));
  if(missing.length){
    const now = new Date().toISOString();
    platform.helpItems.push(...missing.map(item => ({...item, createdAt:now, updatedAt:now})));
    writePlatform(platform);
  }
  return platform;
};
